using System.Text.Json;

namespace MicroEngine.Graphics.Devices;

/// <summary>Bytecode (or MSL source) of one shader in one format, with its entry point.</summary>
/// <param name="Bytes">The code as <see cref="ShaderDescription.Code"/> takes it.</param>
/// <param name="EntryPoint">Entry point name ("main"; "main0" for MSL generated by SPIRV-Cross).</param>
public readonly record struct ShaderCode(ReadOnlyMemory<byte> Bytes, string EntryPoint);

/// <summary>One named value of a uniform block (a field of an HLSL <c>cbuffer</c>).</summary>
/// <param name="Name">The field's name in the shader source.</param>
/// <param name="Offset">Where it starts in the block's data, in bytes.</param>
/// <param name="Size">How many bytes it takes (a <c>float</c> 4, a <c>float2</c> 8, a <c>float3</c> 12, a <c>float4</c> 16, a <c>float4x4</c> 64).</param>
public sealed record ShaderUniform(string Name, int Offset, int Size);

/// <summary>A uniform block of a shader (an HLSL <c>cbuffer</c>): its slot, its size and its named values.</summary>
public sealed class ShaderUniformBlock
{
    /// <summary>Creates the description of a block.</summary>
    /// <exception cref="ArgumentException">A negative slot, a size that is not positive, or a value that leaves the block.</exception>
    public ShaderUniformBlock(string name, int slot, int size, IReadOnlyList<ShaderUniform> uniforms)
    {
        ArgumentNullException.ThrowIfNull(name);
        ArgumentNullException.ThrowIfNull(uniforms);
        if (slot < 0) throw new ArgumentException($"block '{name}': slot {slot} is negative", nameof(slot));
        if (size <= 0) throw new ArgumentException($"block '{name}': its size must be positive", nameof(size));
        foreach (var u in uniforms)
            if (u.Offset < 0 || u.Size <= 0 || u.Offset + u.Size > size)
                throw new ArgumentException($"block '{name}': '{u.Name}' (bytes {u.Offset} to {u.Offset + u.Size}) leaves its {size} bytes", nameof(uniforms));
        (Name, Slot, Size, Uniforms) = (name, slot, size, [.. uniforms]);
    }

    /// <summary>The block's name in the shader source.</summary>
    public string Name { get; }
    /// <summary>The uniform slot the block is bound to (0..n-1).</summary>
    public int Slot { get; }
    /// <summary>The size of the block's data in bytes.</summary>
    public int Size { get; }
    /// <summary>The block's values, in declaration order.</summary>
    public IReadOnlyList<ShaderUniform> Uniforms { get; }
}

/// <summary>A texture a shader samples: its name in the source and its slot.</summary>
/// <param name="Name">The texture's name in the shader source.</param>
/// <param name="Slot">The sampler slot it is bound to (0..n-1).</param>
public sealed record ShaderTextureSlot(string Name, int Slot);

/// <summary>
/// The names a compiled shader's source gives its parameters, as reflection found them when it was compiled: the
/// uniform blocks with each value's place, and the textures. It lets a material's parameters be set by name and
/// checked, the same for every format the shader was compiled to.
/// </summary>
public sealed class ShaderReflection
{
    /// <summary>Creates the description of a shader's parameters.</summary>
    /// <exception cref="ArgumentException">Two blocks or two textures in one slot, or one name used twice.</exception>
    public ShaderReflection(IReadOnlyList<ShaderUniformBlock> blocks, IReadOnlyList<ShaderTextureSlot> textures)
    {
        ArgumentNullException.ThrowIfNull(blocks);
        ArgumentNullException.ThrowIfNull(textures);
        if (blocks.Select(b => b.Slot).Distinct().Count() != blocks.Count) throw new ArgumentException("two uniform blocks share a slot", nameof(blocks));
        if (textures.Select(t => t.Slot).Distinct().Count() != textures.Count) throw new ArgumentException("two textures share a slot", nameof(textures));
        var names = blocks.SelectMany(b => b.Uniforms.Select(u => u.Name)).Concat(textures.Select(t => t.Name)).ToList();
        if (names.Distinct(StringComparer.Ordinal).Count() != names.Count)
            throw new ArgumentException("a parameter name is used twice (names are unique across a shader's blocks and textures)", nameof(blocks));
        (Blocks, Textures) = ([.. blocks.OrderBy(b => b.Slot)], [.. textures.OrderBy(t => t.Slot)]);
    }

    /// <summary>The uniform blocks, by slot.</summary>
    public IReadOnlyList<ShaderUniformBlock> Blocks { get; }
    /// <summary>The textures, by slot.</summary>
    public IReadOnlyList<ShaderTextureSlot> Textures { get; }

    /// <summary>Every parameter name, values first: what a message lists when a name is not one of them.</summary>
    public IEnumerable<string> Names => Blocks.SelectMany(b => b.Uniforms.Select(u => u.Name)).Concat(Textures.Select(t => t.Name));

    /// <summary>The value named <paramref name="name"/> and the block that holds it.</summary>
    public bool TryGetUniform(string name, out ShaderUniformBlock block, out ShaderUniform uniform)
    {
        foreach (var b in Blocks)
            foreach (var u in b.Uniforms)
                if (u.Name == name)
                {
                    (block, uniform) = (b, u);
                    return true;
                }
        (block, uniform) = (null!, null!);
        return false;
    }
}

/// <summary>
/// A shader compiled ahead of time from one HLSL source into every format a tier-1 device may accept (DXIL for
/// Direct3D 12, SPIR-V for Vulkan, MSL for Metal), with the resource counts and parameter names reflection found. It is what
/// <c>microengine shaders</c> writes (one <c>.shader</c> file per HLSL file) and what a game ships: nothing compiles at
/// run time. <see cref="DescriptionFor"/> picks the format a device should be given; a device without custom shaders
/// gets the typed <see cref="GraphicsCapabilityException"/>, as for any undeclared capability.
/// </summary>
/// <remarks>
/// The file is UTF-8 JSON: <c>{"format":"microengine-shader","version":2,"stage":"vertex"|"fragment","source":...,
/// "resources":{"samplers":n,"uniformBuffers":n},"reflection":{"blocks":[{"name":...,"slot":n,"size":n,"uniforms":[{"name":...,
/// "offset":n,"size":n}]}],"textures":[{"name":...,"slot":n}]},"code":{"dxil"|"spirv"|"msl":{"entry":...,"base64":...}}}</c>.
/// A version 1 file has no <c>reflection</c> and is still read: its shader works, with <see cref="Reflection"/> null,
/// so its parameters can only be set by slot. Binding rules are SDL_GPU's (see <see cref="ShaderResources"/>).
/// </remarks>
public sealed class CompiledShader
{
    /// <summary>The file extension of a compiled shader ("sprite.frag.hlsl" compiles to "sprite.frag.shader").</summary>
    public const string FileExtension = ".shader";

    /// <summary>The file format version this assembly writes; it reads this one and every earlier one.</summary>
    public const int FormatVersion = 2;

    private const string Magic = "microengine-shader";
    private static readonly (ShaderFormat Format, string Name)[] Names = [(ShaderFormat.Dxil, "dxil"), (ShaderFormat.SpirV, "spirv"), (ShaderFormat.Msl, "msl")];
    private readonly Dictionary<ShaderFormat, ShaderCode> _code;

    /// <summary>Creates a compiled shader from its code in one or more formats.</summary>
    /// <param name="stage">Stage.</param>
    /// <param name="resources">Reflected resource counts (the same for every format).</param>
    /// <param name="code">Code by format; each key is exactly one format.</param>
    /// <param name="source">The source file it was compiled from, for diagnostics.</param>
    /// <param name="reflection">The names of its parameters, or null when they are not known (a version 1 file).</param>
    /// <exception cref="ArgumentException">No code, a key that is not exactly one format, an empty entry point or code, or names for a slot the resource counts do not have.</exception>
    public CompiledShader(ShaderStage stage, ShaderResources resources, IReadOnlyDictionary<ShaderFormat, ShaderCode> code, string? source = null, ShaderReflection? reflection = null)
    {
        if (reflection is not null)
        {
            if (reflection.Blocks.Any(b => b.Slot >= resources.UniformBuffers))
                throw new ArgumentException($"the reflection names a uniform slot beyond the {resources.UniformBuffers} the shader declares", nameof(reflection));
            if (reflection.Textures.Any(t => t.Slot >= resources.Samplers))
                throw new ArgumentException($"the reflection names a texture slot beyond the {resources.Samplers} the shader samples", nameof(reflection));
        }
        Reflection = reflection;
        ArgumentNullException.ThrowIfNull(code);
        if (code.Count == 0) throw new ArgumentException("a compiled shader needs code in at least one format", nameof(code));
        foreach (var (format, c) in code)
        {
            if (format is not (ShaderFormat.Dxil or ShaderFormat.SpirV or ShaderFormat.Msl)) throw new ArgumentException($"{format} is not exactly one shader format", nameof(code));
            if (c.Bytes.IsEmpty || string.IsNullOrEmpty(c.EntryPoint)) throw new ArgumentException($"{format}: empty code or entry point", nameof(code));
        }
        Stage = stage;
        Resources = resources;
        Source = source;
        _code = new Dictionary<ShaderFormat, ShaderCode>(code);
    }

    /// <summary>Stage.</summary>
    public ShaderStage Stage { get; }

    /// <summary>Reflected resource counts.</summary>
    public ShaderResources Resources { get; }

    /// <summary>The source file it was compiled from, or null.</summary>
    public string? Source { get; }

    /// <summary>The names of the shader's parameters, or null when the file does not carry them (version 1).</summary>
    public ShaderReflection? Reflection { get; }

    /// <summary>The formats this shader has code for.</summary>
    public ShaderFormat Formats => _code.Keys.Aggregate(ShaderFormat.None, (all, f) => all | f);

    /// <summary>The code in <paramref name="format"/>, if compiled for it.</summary>
    public bool TryGetCode(ShaderFormat format, out ShaderCode code) => _code.TryGetValue(format, out code);

    /// <summary>
    /// The description to give a device with <paramref name="capabilities"/>: the format its API runs natively
    /// (DXIL on Direct3D 12, MSL on Metal, SPIR-V on Vulkan), otherwise the first format both sides have.
    /// </summary>
    /// <exception cref="GraphicsCapabilityException">The device declares no custom shaders (<see cref="GraphicsFeatures.Shaders"/>), or none of the formats this shader was compiled for.</exception>
    public ShaderDescription DescriptionFor(GraphicsCapabilities capabilities)
    {
        ArgumentNullException.ThrowIfNull(capabilities);
        if (!capabilities.Has(GraphicsFeatures.Shaders)) throw new GraphicsCapabilityException("CreateShader", capabilities.Backend, GraphicsFeatures.Shaders);
        var preferred = capabilities.ApiName switch { "direct3d12" => ShaderFormat.Dxil, "metal" => ShaderFormat.Msl, "vulkan" => ShaderFormat.SpirV, _ => ShaderFormat.None };
        ShaderFormat chosen = preferred != ShaderFormat.None && (capabilities.ShaderFormats & preferred) != 0 && _code.ContainsKey(preferred) ? preferred
            : Names.Select(n => n.Format).FirstOrDefault(f => (capabilities.ShaderFormats & f) != 0 && _code.ContainsKey(f));
        if (chosen == ShaderFormat.None)
            throw new GraphicsCapabilityException("CreateShader", capabilities.Backend, GraphicsFeatures.None,
                $"a shader format the device accepts (device: {capabilities.ShaderFormats}; compiled: {Formats})");
        var code = _code[chosen];
        return new ShaderDescription(Stage, chosen, code.Bytes, code.EntryPoint, Resources);
    }

    /// <summary>Creates the shader on <paramref name="device"/> in the format <see cref="DescriptionFor"/> picks.</summary>
    /// <exception cref="GraphicsCapabilityException">See <see cref="DescriptionFor"/>.</exception>
    public Shader Create(IGraphicsDevice device)
    {
        ArgumentNullException.ThrowIfNull(device);
        return device.CreateShader(DescriptionFor(device.Capabilities));
    }

    /// <summary>Reads a compiled shader file.</summary>
    /// <exception cref="InvalidDataException">The data is not a compiled shader of a version this assembly reads.</exception>
    public static CompiledShader Parse(ReadOnlySpan<byte> utf8Json)
    {
        try
        {
            using var document = JsonDocument.Parse(utf8Json.ToArray());
            var root = document.RootElement;
            if (root.ValueKind != JsonValueKind.Object || !root.TryGetProperty("format", out var magic) || magic.GetString() != Magic)
                throw new InvalidDataException("not a compiled shader (\"format\": \"microengine-shader\" is missing)");
            int version = root.GetProperty("version").GetInt32();
            if (version < 1 || version > FormatVersion)
                throw new InvalidDataException($"compiled shader version {version}; this engine reads versions 1 to {FormatVersion} (recompile with this SDK's microengine shaders)");
            var stage = root.GetProperty("stage").GetString() switch
            {
                "vertex" => ShaderStage.Vertex,
                "fragment" => ShaderStage.Fragment,
                var s => throw new InvalidDataException($"unknown shader stage '{s}'"),
            };
            var r = root.GetProperty("resources");
            int Count(string name) => r.TryGetProperty(name, out var v) ? v.GetInt32() : 0;
            var resources = new ShaderResources(Count("samplers"), Count("uniformBuffers"), Count("storageTextures"), Count("storageBuffers"));
            var code = new Dictionary<ShaderFormat, ShaderCode>();
            foreach (var entry in root.GetProperty("code").EnumerateObject())
            {
                var format = Names.FirstOrDefault(n => n.Name == entry.Name).Format;
                if (format == ShaderFormat.None) throw new InvalidDataException($"unknown shader format '{entry.Name}'");
                code[format] = new ShaderCode(Convert.FromBase64String(entry.Value.GetProperty("base64").GetString()!), entry.Value.GetProperty("entry").GetString()!);
            }
            string? source = root.TryGetProperty("source", out var src) ? src.GetString() : null;
            ShaderReflection? reflection = null;
            if (root.TryGetProperty("reflection", out var reflected))
            {
                var blocks = new List<ShaderUniformBlock>();
                foreach (var b in reflected.GetProperty("blocks").EnumerateArray())
                {
                    var uniforms = new List<ShaderUniform>();
                    foreach (var u in b.GetProperty("uniforms").EnumerateArray())
                        uniforms.Add(new ShaderUniform(u.GetProperty("name").GetString()!, u.GetProperty("offset").GetInt32(), u.GetProperty("size").GetInt32()));
                    blocks.Add(new ShaderUniformBlock(b.GetProperty("name").GetString()!, b.GetProperty("slot").GetInt32(), b.GetProperty("size").GetInt32(), uniforms));
                }
                var textures = new List<ShaderTextureSlot>();
                foreach (var t in reflected.GetProperty("textures").EnumerateArray())
                    textures.Add(new ShaderTextureSlot(t.GetProperty("name").GetString()!, t.GetProperty("slot").GetInt32()));
                reflection = new ShaderReflection(blocks, textures);
            }
            return new CompiledShader(stage, resources, code, source, reflection);
        }
        catch (Exception e) when (e is JsonException or KeyNotFoundException or FormatException or InvalidOperationException or ArgumentException)
        {
            throw new InvalidDataException($"invalid compiled shader: {e.Message}", e);
        }
    }

    /// <summary>The file form of this shader (UTF-8 JSON, formats in a fixed order, so the same compilation gives the same bytes).</summary>
    public byte[] ToBytes()
    {
        using var stream = new MemoryStream();
        using (var w = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            w.WriteStartObject();
            w.WriteString("format", Magic);
            w.WriteNumber("version", FormatVersion);
            w.WriteString("stage", Stage == ShaderStage.Vertex ? "vertex" : "fragment");
            if (Source is not null) w.WriteString("source", Source);
            w.WriteStartObject("resources");
            w.WriteNumber("samplers", Resources.Samplers);
            w.WriteNumber("uniformBuffers", Resources.UniformBuffers);
            w.WriteNumber("storageTextures", Resources.StorageTextures);
            w.WriteNumber("storageBuffers", Resources.StorageBuffers);
            w.WriteEndObject();
            if (Reflection is not null)
            {
                w.WriteStartObject("reflection");
                w.WriteStartArray("blocks");
                foreach (var block in Reflection.Blocks)
                {
                    w.WriteStartObject();
                    w.WriteString("name", block.Name);
                    w.WriteNumber("slot", block.Slot);
                    w.WriteNumber("size", block.Size);
                    w.WriteStartArray("uniforms");
                    foreach (var uniform in block.Uniforms)
                    {
                        w.WriteStartObject();
                        w.WriteString("name", uniform.Name);
                        w.WriteNumber("offset", uniform.Offset);
                        w.WriteNumber("size", uniform.Size);
                        w.WriteEndObject();
                    }
                    w.WriteEndArray();
                    w.WriteEndObject();
                }
                w.WriteEndArray();
                w.WriteStartArray("textures");
                foreach (var texture in Reflection.Textures)
                {
                    w.WriteStartObject();
                    w.WriteString("name", texture.Name);
                    w.WriteNumber("slot", texture.Slot);
                    w.WriteEndObject();
                }
                w.WriteEndArray();
                w.WriteEndObject();
            }
            w.WriteStartObject("code");
            foreach (var (format, name) in Names)
            {
                if (!_code.TryGetValue(format, out var c)) continue;
                w.WriteStartObject(name);
                w.WriteString("entry", c.EntryPoint);
                w.WriteBase64String("base64", c.Bytes.Span);
                w.WriteEndObject();
            }
            w.WriteEndObject();
            w.WriteEndObject();
        }
        stream.WriteByte((byte)'\n');
        return stream.ToArray();
    }

    /// <inheritdoc/>
    public override string ToString() => $"{Source ?? "shader"} ({Stage}, {Formats})";
}
